import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform, time, positionWorld, normalWorld, vec2, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  // ── Configuration extraction ────────────────────────────────────────
  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const gradientStops = vs.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const effects = vs.effects ?? {};
  const typography = vs.typography ?? {};
  const textItems = config.textContent ?? vs.textContent ?? [];

  // Colors to vec3
  const c1 = new THREE.Color(gradientStops[0].hex);
  const c2 = new THREE.Color(gradientStops[1].hex);
  const c3 = new THREE.Color(gradientStops[2].hex);
  const stop1 = gradientStops[0].at;
  const stop2 = gradientStops[1].at;
  const stop3 = gradientStops[2].at;

  // ── Geometry helpers ────────────────────────────────────────────────
  function createRoundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  const buttonW = 2.6;
  const buttonH = 0.68;
  const cornerR = 0.08;
  const bevelDepth = 0.03;
  const bevelSize = 0.03;

  // Main button shape
  const mainShape = createRoundedRectShape(buttonW, buttonH, cornerR);
  const extrudeSettings = {
    depth: bevelDepth,
    bevelEnabled: true,
    bevelThickness: bevelDepth,
    bevelSize: bevelSize,
    bevelSegments: 1,
  };
  const mainGeom = new THREE.ExtrudeGeometry(mainShape, extrudeSettings);
  mainGeom.computeVertexNormals();

  // Emissive rim shape (slightly larger)
  const rimW = buttonW + 0.03; // 0.015 per side
  const rimH = buttonH + 0.03;
  const rimShape = createRoundedRectShape(rimW, rimH, cornerR);
  const rimGeom = new THREE.ExtrudeGeometry(rimShape, extrudeSettings);
  rimGeom.computeVertexNormals();

  // ── Material construction (TSL nodes) ───────────────────────────────
  const gradientNode = Fn(() => {
    const u = uv();
    // Gradients are vertical (v coordinate). Mapping: v=0 at bottom, v=1 at top
    const v = u.y;
    // Hard seam at 50% face height
    const seam = 0.5;
    // First segment: stop1 to stop2
    const t1 = smoothstep(stop1, stop2, v);
    const color12 = mix(c1, c2, t1);
    // Second segment: stop2 to stop3
    const t2 = smoothstep(stop2, stop3, v);
    const color23 = mix(c2, c3, t2);
    // Select based on side of seam (strict)
    const seamColor = mix(c1, c3, smoothstep(0.48, 0.52, v)); // hard edge; we'll simplify to just mix
    // Simpler: two-stop gradient with a sharp transition at 50%
    // Actually use a piecewise: if v < 0.5: gradient from stop1 to stop2, else from stop2 to stop3 with a hard edge
    const isTop = v.greaterThan(0.5);
    const lowV = v.mul(2); // remap 0-0.5 to 0-1
    const highV = v.sub(0.5).mul(2);
    const colorLow = mix(c1, c2, smoothstep(stop1, stop2, lowV));
    const colorHigh = mix(c2, c3, smoothstep(stop2, stop3, highV));
    const final = mix(colorLow, colorHigh, isTop);
    return final;
  });

  // Main button material
  const mainMat = new MeshStandardNodeMaterial();
  mainMat.colorNode = gradientNode();
  mainMat.roughness = 0.5;
  mainMat.metalness = 0.35;
  mainMat.clearcoat = 0.22;
  mainMat.emissiveNode = vec3(0, 0, 0); // no emissive; rim will handle
  mainMat.emissiveIntensity = 0;

  // Emissive rim material
  const rimMat = new MeshStandardNodeMaterial();
  rimMat.colorNode = vec3(0);
  rimMat.emissive = new THREE.Color(colors.accent); // #ff2a38
  rimMat.emissiveIntensity = 1.6;
  rimMat.roughness = 0.5;
  rimMat.metalness = 0.35;
  rimMat.clearcoat = 0.22;

  // ── Meshes ──────────────────────────────────────────────────────────
  const mainMesh = new THREE.Mesh(mainGeom, mainMat);
  const rimMesh = new THREE.Mesh(rimGeom, rimMat);
  rimMesh.position.z = -0.0001; // slightly behind to avoid z-fighting

  // ── Text elements ───────────────────────────────────────────────────
  const buttonGroup = new THREE.Group();
  buttonGroup.add(mainMesh);
  buttonGroup.add(rimMesh);

  // Place text
  const labelText = textItems.find(item => item.role === 'cta-label')?.text || 'BEGIN COMMISSION';
  const captionText = textItems.find(item => item.role === 'caption')?.text || 'NO DEPOSIT REQUIRED';

  const labelOpts = {
    fontSize: 0.2, // matches cta-label fontSize design token
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.08,
  };
  const captionOpts = {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.12,
  };

  const labelMesh = ctx.fontAtlas.createText(labelText, labelOpts);
  labelMesh.position.set(0, 0, bevelDepth + 0.005); // slightly above front face
  labelMesh.scale.set(1, 1, 1);

  const captionMesh = ctx.fontAtlas.createText(captionText, captionOpts);
  captionMesh.position.set(0, -0.25, bevelDepth + 0.005); // 0.25 below button
  captionMesh.scale.set(1, 1, 1);

  buttonGroup.add(labelMesh);
  buttonGroup.add(captionMesh);

  // ── Contact shadow plane ────────────────────────────────────────────
  const shadowGeom = new THREE.PlaneGeometry(buttonW * 1.5, buttonH * 1.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.08 - bevelDepth; // 0.08 below button base
  shadowMesh.rotation.x = -Math.PI / 2;
  buttonGroup.add(shadowMesh);

  // ── Mount motion: weighted settle ───────────────────────────────────
  buttonGroup.scale.set(1.04, 1.04, 1.04);
  const settleTimeline = gsap.timeline();
  settleTimeline.to(buttonGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // ── Interaction handlers ────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;

  function onPointerEnter() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(buttonGroup.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'power1.out', // cubic-bezier(0.25,0.46,0.45,0.94) approximated
    });
    hoverTimeline.to(rimMat, {
      emissiveIntensity: 2.2,
      duration: 0.18,
      ease: 'power1.out',
    }, 0);
  }

  function onPointerLeave() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(buttonGroup.position, {
      z: 0,
      duration: 0.18,
      ease: 'power1.out',
    });
    hoverTimeline.to(rimMat, {
      emissiveIntensity: 1.6,
      duration: 0.18,
      ease: 'power1.out',
    }, 0);
  }

  function onPointerDown() {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(buttonGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)', // cubic-bezier(0.175,0.885,0.32,1.275)
    });
    pressTimeline.to(shadowMesh.scale, {
      x: 0.85,
      y: 0.85,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
  }

  function onPointerUp() {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(buttonGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    pressTimeline.to(shadowMesh.scale, {
      x: 1,
      y: 1,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
  }

  buttonGroup.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
  };

  // ── Cleanup ─────────────────────────────────────────────────────────
  buttonGroup.userData.cleanup = () => {
    settleTimeline.kill();
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    mainGeom.dispose();
    rimGeom.dispose();
    shadowGeom.dispose();
    mainMat.dispose();
    rimMat.dispose();
    shadowMat.dispose();
    // Text meshes are simple; no need to dispose font atlas
  };

  return buttonGroup;
}
